2	  import { tick } from 'svelte';
3	  import {
4	    previewOAuthConsent,
5	    previewOAuthConsentByRequestId,
6	    confirmOAuthConsent,
7	    scanQrCode,
8	    cancelQrScan,
9	    isCodedError,
10	    type ConsentPreview,
11	    type ConsentError,
12	  } from '$lib/ipc';
13	  import { parseConsentQr } from '$lib/consent-qr';
14	  import { authenticateBiometric } from '$lib/biometric';
15	  import { describeScope } from '$lib/agent-scopes';
16	  import Button from '$lib/components/ui/Button.svelte';
17	  import TextField from '$lib/components/ui/TextField.svelte';
18	  import Spinner from '$lib/components/ui/Spinner.svelte';
19	  import ScreenHeader from '$lib/components/ui/ScreenHeader.svelte';
20	
21	  let {
22	    did,
23	    handle,
24	    onback,
25	    ondone,
26	  }: {
27	    did: string;
28	    /** The identity's handle, shown as "as @{handle}"; falls back to the DID when absent. */
29	    handle?: string;
30	    onback: () => void;
31	    /** Called after a recorded decision (approve or deny). */
32	    ondone: () => void;
33	  } = $props();
34	
35	  type Phase = 'enter' | 'loading' | 'review' | 'approving' | 'denying' | 'approved' | 'denied';
36	
37	  let phase = $state<Phase>('enter');
38	  let code = $state('');
39	  let codeError = $state<string | undefined>(undefined);
40	  let preview = $state<ConsentPreview | null>(null);
41	  /** Non-`atproto` scope tokens the user has left checked (scope reduction lives here). */
42	  let checked = $state<Set<string>>(new Set());
43	  let ceremonyError = $state<{ title: string; body: string } | null>(null);
44	
45	  // ── QR scan (Phase B: cross-device convenience channel) ──────────────────────
46	  // `scanning` makes the WebView see-through so the native camera the barcode-scanner plugin
47	  // renders BEHIND the web layer is visible; the overlay draws only the framing. A monotonic
48	  // `scanToken` supersedes an in-flight scan so a late-settling scanQrCode() (or a Cancel) can't
49	  // touch shared state. `scanHint` carries the "no camera / bad QR" fallback nudge to the typed code.
50	  let scanning = $state(false);
51	  let scanHint = $state<string | undefined>(undefined);
52	  let scanToken = 0;
53	  let overlayEl = $state<HTMLDivElement | undefined>();
54	  let triggerEl = $state<HTMLDivElement | undefined>();
55	
56	  const asWho = $derived(handle ? `@${handle}` : did);
57	  const clientLabel = $derived(preview?.clientName ?? preview?.clientId ?? 'an app');
58	  const originLabel = $derived(preview ? originOf(preview) : '');
59	  /** Non-`atproto` requested tokens, each with a plain-language description, for the checkboxes. */
60	  let optionalScopes = $derived(
61	    preview
62	      ? preview.requestedScope.filter((t) => t !== 'atproto').map((t) => describeScope(t))
63	      : []
64	  );
65	
66	  function originOf(p: ConsentPreview): string {
67	    if (p.origin) {
68	      try {
69	        return new URL(p.origin).host;
70	      } catch {
71	        return p.origin;
72	      }
73	    }
74	    try {
75	      return new URL(p.redirectUri).host;
76	    } catch {
77	      return p.redirectUri;
78	    }
79	  }
80	
81	  function errorCode(e: unknown): ConsentError['code'] | 'UNEXPECTED' {
82	    if (isCodedError(e)) return (e as ConsentError).code;
83	    return 'UNEXPECTED';
84	  }
85	
86	  function decisionFailure(codeName: string): { title: string; body: string } {
87	    switch (codeName) {
88	      case 'REQUEST_NOT_FOUND':
89	        return {
90	          title: 'This request expired',
91	          body: 'Sign-in requests are only valid for a few minutes. Return to the app and start again, then enter the new code.',
92	        };
93	      case 'ALREADY_RESOLVED':
94	        return {
95	          title: 'Already handled',
96	          body: 'This sign-in request has already been approved or denied. Return to the app and start again if needed.',
97	        };
98	      case 'APPROVAL_REJECTED':
99	        return {
100	          title: 'Your server rejected the approval',
101	          body: 'The signature could not be verified against your identity’s current keys. Nothing was granted.',
102	        };
103	      case 'RATE_LIMITED':
104	        return {
105	          title: 'Too many attempts',
106	          body: 'Your server paused sign-in checks for a few minutes. Wait, then try again.',
107	        };
108	      default:
109	        return {
110	          title: 'Could not complete the request',
111	          body: 'Your server could not record the decision. Nothing was granted — you can try again.',
112	        };
113	    }
114	  }
115	
116	  /** The verbatim granted-scope string the wallet signs: `atproto` (always) + every checked token. */
117	  function grantedScopeString(): string {
118	    if (!preview) return 'atproto';
119	    return preview.requestedScope
120	      .filter((t) => t === 'atproto' || checked.has(t))
121	      .join(' ');
122	  }
123	
124	  function toggle(token: string) {
125	    const next = new Set(checked);
126	    if (next.has(token)) next.delete(token);
127	    else next.add(token);
128	    checked = next;
129	  }
130	
131	  /** Accept a fetched preview: default scope reduction to "grant everything requested", then review. */
132	  function applyPreview(p: ConsentPreview) {
133	    preview = p;
134	    checked = new Set(p.requestedScope.filter((t) => t !== 'atproto'));
135	    phase = 'review';
136	  }
137	
138	  async function loadPreview() {
139	    codeError = undefined;
140	    ceremonyError = null;
141	    const trimmed = code.trim().toUpperCase();
142	    if (!trimmed) {
143	      codeError = 'Enter the code shown on the sign-in page.';
144	      return;
145	    }
146	    phase = 'loading';
147	    try {
148	      applyPreview(await previewOAuthConsent(did, trimmed));
149	      code = trimmed;
150	    } catch (e) {
151	      phase = 'enter';
152	      const c = errorCode(e);
153	      if (c === 'REQUEST_NOT_FOUND') {
154	        codeError = 'That code was not recognized or has expired. Check it and try again.';
155	      } else if (c === 'RATE_LIMITED') {
156	        ceremonyError = decisionFailure(c);
157	      } else {
158	        codeError = 'Could not reach your server. Check your connection and try again.';
159	      }
160	    }

1	// pattern: Imperative Shell
2	//
3	// The wallet-confirmed half of OAuth consent. Three public routes plus a wallet preview, all keyed
4	// off the single-use `pending_oauth_authorizations` request the consent page
5	// (`oauth_authorize::get_authorization`) created:
6	//
7	//   GET  /oauth/authorize/consent-request  — wallet preview: client/origin/scope for a user_code
8	//   GET  /oauth/authorize/status           — browser poll (slow_down-throttled), returns {status}
9	//   POST /oauth/authorize/approve          — device-key-signed approve/deny of a request
10	//   POST /oauth/authorize/complete         — browser exchanges an approved request for the code
11	//
12	// Approval is proven with a canonical device-key envelope in the `sovereign_session` mold
13	// (`crypto::encode_oauth_consent_envelope`), verified against the account's **authoritative**
14	// current signing authority (`identity::authority` — a did:plc rotation set, or a self-hosted
15	// did:web's `#device` key) — never the cached DID doc. The envelope binds `request_id`, `client_id`, the
16	// decision, and a hash of the granted scope set, so an approval cannot be replayed onto a different
17	// request, flipped from a denial, or widened. Replay of the same envelope onto its own request is
18	// stopped by the single-use guarded status transition (the request_id binding + single-use row
19	// together subsume a nonce store). This module never imports another route handler.
20	
21	use std::time::{Duration, Instant};
22	
23	use axum::{
24	    extract::{Form, Query, State},
25	    http::StatusCode,
26	    response::{IntoResponse, Json, Response},
27	};
28	use common::{ApiError, ErrorCode, SOVEREIGN_TIMESTAMP_WINDOW_SECS};
29	use serde::{Deserialize, Serialize};
30	
31	use crate::app::AppState;
32	use crate::auth::signed_proof::{decode_canonical_base64url, NONCE_BYTES, SIGNATURE_BYTES};
33	use crate::auth::token::generate_token;
34	use crate::db::oauth::store_authorization_code;
35	use crate::db::pending_oauth_authorizations::{
36	    approve_pending_authorization, complete_pending_authorization, deny_pending_authorization,
37	    get_pending_by_request_id, get_pending_by_user_code, insert_oauth_consent_audit_event,
38	    OAuthConsentAuditEventType,
39	};
40	use crate::identity::authority::{authorized_signing_keys, AuthorityError};
41	use crate::routes::oauth_templates::{build_code_redirect, error_page};
42	
43	/// Minimum spacing between accepted status polls for one request; a faster poll gets the
44	/// `slow_down` 429 the page's JS backs off on (the `claim_polling` discipline).
45	const STATUS_POLL_MIN_INTERVAL: Duration = Duration::from_secs(2);
46	
47	// ── Shared helpers ──────────────────────────────────────────────────────────────
48	
49	/// A request that is no longer approvable — absent, terminal, or lapsed — maps to one uniform
50	/// response so the caller can't probe request state beyond "pending or not".
51	fn not_approvable() -> ApiError {
52	    ApiError::new(
53	        ErrorCode::NotFound,
54	        "authorization request not found or expired",
55	    )
56	}
57	
58	/// Signature / authority / binding failures share one message so the surface reveals nothing about
59	/// which check failed.
60	fn approval_rejected() -> ApiError {
61	    ApiError::new(
62	        ErrorCode::AuthenticationRequired,
63	        "consent approval rejected",
64	    )
65	}
66	
67	/// Reduce the wallet's requested granted-scope string to the tokens actually on offer: `atproto` is
68	/// always granted (never optional), and every other token is kept only if it was part of the
69	/// request's snapshotted `requested_scope`. This mirrors `oauth_authorize`'s reduction filter, so a
70	/// tampered/injected token that was never requested cannot add scope — only narrow it.
71	fn reduce_granted_scope(requested_scope: &str, wallet_granted: &str) -> String {
72	    let wallet: Vec<&str> = wallet_granted.split_whitespace().collect();
73	    requested_scope
74	        .split_whitespace()
75	        .filter(|t| *t == "atproto" || wallet.contains(t))
76	        .collect::<Vec<_>>()
77	        .join(" ")
78	}
79	
80	// ── Preview ─────────────────────────────────────────────────────────────────────
81	
82	#[derive(Deserialize)]
83	pub struct ConsentRequestQuery {
84	    /// Typed path: the human-entered `user_code`. Exactly one of `user_code` / `request_id`.
85	    user_code: Option<String>,
86	    /// Handoff path: the `request_id` carried by the "Open in Obsign" link.
87	    request_id: Option<String>,
88	}
89	
90	#[derive(Serialize)]
91	#[serde(rename_all = "camelCase")]
92	pub struct ConsentRequestPreview {
93	    request_id: String,
94	    client_id: String,
95	    client_name: Option<String>,
96	    redirect_uri: String,
97	    origin: Option<String>,
98	    ip: Option<String>,
99	    requested_scope: Vec<String>,
100	    login_hint: Option<String>,
101	}
102	
103	/// `GET /oauth/authorize/consent-request` — the wallet's preview of a pending request, resolved by
104	/// `user_code` (typed) or `request_id` (handoff). Returns 404 for anything not currently pending so
105	/// a guessed code reveals nothing.
106	pub async fn get_consent_request(
107	    State(state): State<AppState>,
108	    Query(query): Query<ConsentRequestQuery>,
109	) -> Result<Json<ConsentRequestPreview>, ApiError> {
110	    let pending = match (&query.user_code, &query.request_id) {
111	        (Some(code), None) => get_pending_by_user_code(&state.db, code).await?,
112	        (None, Some(request_id)) => get_pending_by_request_id(&state.db, request_id).await?,
113	        _ => {
114	            return Err(ApiError::new(
115	                ErrorCode::InvalidRequest,
116	                "exactly one of userCode or requestId is required",
117	            ))
118	        }
119	    };
120	    let pending = pending.filter(|p| p.status == "pending" && !p.is_expired);
121	    let Some(p) = pending else {
122	        return Err(not_approvable());
123	    };
124	    Ok(Json(ConsentRequestPreview {
125	        request_id: p.request_id,
126	        client_id: p.client_id,
127	        client_name: p.client_name,
128	        redirect_uri: p.redirect_uri,
129	        origin: p.origin,
130	        ip: p.ip,
131	        requested_scope: p
132	            .requested_scope
133	            .split_whitespace()
134	            .map(str::to_string)
135	            .collect(),
136	        login_hint: p.login_hint,
137	    }))
138	}
139	
140	// ── Status poll ─────────────────────────────────────────────────────────────────
141	
142	#[derive(Deserialize)]
143	pub struct StatusQuery {
144	    request_id: String,
145	}
146	
147	#[derive(Serialize)]
148	struct StatusResponse {
149	    status: &'static str,
150	}
151	
152	/// `GET /oauth/authorize/status?request_id=…` — the consent page's poll. Throttled per request with
153	/// the `slow_down` discipline (429 when polled faster than `STATUS_POLL_MIN_INTERVAL`), and reports
154	/// a derived `expired` for a lapsed or reclaimed request so the page stops.
155	pub async fn get_authorization_status(
156	    State(state): State<AppState>,
157	    Query(query): Query<StatusQuery>,
158	) -> Response {
159	    // slow_down throttle, reusing the shared poll tracker with a namespaced key so it can't collide
160	    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
161	    {
162	        let key = format!("consent:{}", query.request_id);
163	        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
164	        if let Some(last) = tracker.get(&key) {
165	            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
166	                return (
167	                    StatusCode::TOO_MANY_REQUESTS,
168	                    Json(StatusResponse {
169	                        status: "slow_down",
170	                    }),
171	                )
172	                    .into_response();
173	            }
174	        }
175	        tracker.insert(key, Instant::now());
176	    }
177	
178	    let pending = match get_pending_by_request_id(&state.db, &query.request_id).await {
179	        Ok(p) => p,
180	        Err(e) => return e.into_response(),
181	    };
182	    let status = match pending {
183	        // Absent (never created or reclaimed) reads as expired so the page stops polling.
184	        None => "expired",
185	        Some(p) if p.status == "pending" && p.is_expired => "expired",
186	        Some(p) => match p.status.as_str() {
187	            "pending" => "pending",
188	            "approved" => "approved",
189	            "denied" => "denied",
190	            "completed" => "completed",
191	            _ => "expired",
192	        },
193	    };
194	    Json(StatusResponse { status }).into_response()
195	}
196	
197	// ── Approve / deny ──────────────────────────────────────────────────────────────
198	
199	#[derive(Deserialize)]
200	#[serde(rename_all = "camelCase", deny_unknown_fields)]
201	pub struct ApprovalRequest {
202	    did: String,
203	    signing_key: String,
204	    request_id: String,
205	    /// `"approve"` or `"deny"` — bound into the signed envelope so a captured denial cannot be
206	    /// replayed as an approval.
207	    decision: String,
208	    /// Space-joined granted-scope string the wallet chose (empty for a denial). Signed verbatim.
209	    #[serde(default)]
210	    granted_scope: String,
211	    timestamp: i64,
212	    nonce: String,
213	    signature: String,
214	}
215	
216	#[derive(Serialize)]
217	#[serde(rename_all = "camelCase")]
218	pub struct ApprovalResponse {
219	    status: &'static str,
220	    did: String,
221	}
222	
223	/// `POST /oauth/authorize/approve` — verify a device-key-signed approve/deny envelope against the
224	/// account's authoritative current signing authority and terminate the request accordingly.
225	pub async fn post_authorization_approve(
226	    State(state): State<AppState>,
227	    Json(request): Json<ApprovalRequest>,
228	) -> Result<Json<ApprovalResponse>, ApiError> {
229	    // 1. Cheap syntactic gates before any DB or network work.
230	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
231	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
232	        .ok_or_else(approval_rejected)?;
233	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
234	        return Err(approval_rejected());
235	    }
236	    let approve = match request.decision.as_str() {
237	        crypto::OAUTH_CONSENT_DECISION_APPROVE => true,
238	        crypto::OAUTH_CONSENT_DECISION_DENY => false,
239	        _ => return Err(approval_rejected()),
240	    };
241	    let now = crate::time::unix_now_secs();
242	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
243	        return Err(approval_rejected());
244	    }
245	
246	    // 2. Load the pending request; it must be currently approvable.
247	    let pending = get_pending_by_request_id(&state.db, &request.request_id)
248	        .await?
249	        .filter(|p| p.status == "pending" && !p.is_expired)
250	        .ok_or_else(not_approvable)?;
251	
252	    // 3. Account binding: a pre-bound login_hint must match the approving DID; otherwise the wallet
253	    //    binds its own DID here (like the agent claim confirm). Either way the DID must be a local
254	    //    active account so the authorization code can be issued against it.
255	    if let Some(hint) = pending.login_hint.as_deref() {
256	        if hint != request.did {
257	            return Err(approval_rejected());
258	        }
259	    }
260	    if !crate::db::accounts::active_local_account_exists(&state.db, &request.did).await? {
261	        return Err(approval_rejected());
262	    }
263	
264	    // 4. The granted scope the wallet signed over is the verbatim `granted_scope` string (empty for
265	    //    a denial); the stored set is that, reduced to what was actually requested.
266	    let signed_scope = if approve {
267	        request.granted_scope.as_str()
268	    } else {
269	        ""
270	    };
271	    let stored_scope = reduce_granted_scope(&pending.requested_scope, signed_scope);
272	
273	    // 5. Verify the envelope signature, then confirm the signing key is in the account's
274	    //    authoritative current signing authority (never the cached DID doc). Signature first, so an
275	    //    invalid signature never triggers the outbound authority lookup.
276	    let server_did = state.config.resolve_server_did();
277	    let envelope = crypto::encode_oauth_consent_envelope(
278	        &server_did,
279	        &request.did,
280	        &request.signing_key,
281	        &request.request_id,
282	        &pending.client_id,
283	        &request.decision,
284	        signed_scope,
285	        request.timestamp,
286	        &request.nonce,
287	    );
288	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
289	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature)
290	        .map_err(|_| approval_rejected())?;
291	
292	    let authority = authorized_signing_keys(&state, &request.did)
293	        .await
294	        .map_err(|error| match error {
295	            AuthorityError::Unauthorized(_) => approval_rejected(),
296	            AuthorityError::Lookup(err) => err,
297	        })?;
298	    if !authority.authorizes(&request.signing_key) {
299	        return Err(approval_rejected());
300	    }
301	
302	    // 6. Terminate the request and audit it in one transaction. The guarded UPDATE is the single-use
303	    //    point: a replayed envelope lands on an already-terminal row and wins nothing.
304	    let mut tx = state.db.begin().await.map_err(|e| {
305	        tracing::error!(error = %e, "failed to begin consent approval transaction");
306	        ApiError::new(ErrorCode::InternalError, "failed to record decision")
307	    })?;
308	    let won = if approve {
309	        approve_pending_authorization(&mut *tx, &request.request_id, &request.did, &stored_scope)
310	            .await?
311	    } else {
312	        deny_pending_authorization(&mut *tx, &request.request_id, &request.did).await?
313	    };
314	    if !won {
315	        return Err(ApiError::new(
316	            ErrorCode::InvalidRequest,
317	            "authorization request already resolved",
318	        ));
319	    }
320	    let (event, detail) = if approve {
321	        (
322	            OAuthConsentAuditEventType::Approved,
323	            serde_json::json!({ "granted_scope": stored_scope }).to_string(),
324	        )
325	    } else {
326	        (
327	            OAuthConsentAuditEventType::Denied,
328	            serde_json::json!({}).to_string(),
329	        )
330	    };
331	    insert_oauth_consent_audit_event(
332	        &mut *tx,
333	        &uuid::Uuid::new_v4().to_string(),
334	        &request.request_id,
335	        Some(&request.did),
336	        &pending.client_id,
337	        event,
338	        Some(&detail),
339	    )
340	    .await?;

