1	// pattern: Imperative Shell
2	//
3	// The wallet-confirmed half of OAuth consent. Three public routes plus a wallet preview, all keyed
4	// off the single-use `pending_oauth_authorizations` request the consent page
5	// (`oauth_authorize::get_authorization`) created:
6	//
7	//   GET  /oauth/authorize/consent-request  — wallet preview: client/origin/scope for a user_code
8	//   GET  /oauth/authorize/status           — browser poll (slow_down-throttled), returns {status}
9	//   POST /oauth/authorize/approve          — device-key-signed approve/deny of a request
10	//   POST /oauth/authorize/complete         — browser exchanges an approved request for the code
11	//
12	// Approval is proven with a canonical device-key envelope in the `sovereign_session` mold
13	// (`crypto::encode_oauth_consent_envelope`), verified against the account's **authoritative**
14	// current signing authority (`identity::authority` — a did:plc rotation set, or a self-hosted
15	// did:web's `#device` key) — never the cached DID doc. The envelope binds `request_id`, `client_id`, the
16	// decision, and a hash of the granted scope set, so an approval cannot be replayed onto a different
17	// request, flipped from a denial, or widened. Replay of the same envelope onto its own request is
18	// stopped by the single-use guarded status transition (the request_id binding + single-use row
19	// together subsume a nonce store). This module never imports another route handler.
20	
21	use std::time::{Duration, Instant};
22	
23	use axum::{
24	    extract::{Form, Query, State},
25	    http::StatusCode,
26	    response::{IntoResponse, Json, Response},
27	};
28	use common::{ApiError, ErrorCode, SOVEREIGN_TIMESTAMP_WINDOW_SECS};
29	use serde::{Deserialize, Serialize};
30	
31	use crate::app::AppState;
32	use crate::auth::signed_proof::{decode_canonical_base64url, NONCE_BYTES, SIGNATURE_BYTES};
33	use crate::auth::token::generate_token;
34	use crate::db::oauth::store_authorization_code;
35	use crate::db::pending_oauth_authorizations::{
36	    approve_pending_authorization, complete_pending_authorization, deny_pending_authorization,
37	    get_pending_by_request_id, get_pending_by_user_code, insert_oauth_consent_audit_event,
38	    OAuthConsentAuditEventType,
39	};
40	use crate::identity::authority::{authorized_signing_keys, AuthorityError, AuthoritySet};
41	use crate::identity::resolution::resolve_handle_to_did;
42	use crate::routes::oauth_templates::{build_code_redirect, error_page};
43	
44	/// Minimum spacing between accepted status polls for one request; a faster poll gets the
45	/// `slow_down` 429 the page's JS backs off on (the `claim_polling` discipline).
46	const STATUS_POLL_MIN_INTERVAL: Duration = Duration::from_secs(2);
47	
48	// ── Shared helpers ──────────────────────────────────────────────────────────────
49	
50	/// A request that is no longer approvable — absent, terminal, or lapsed — maps to one uniform
51	/// response so the caller can't probe request state beyond "pending or not".
52	fn not_approvable() -> ApiError {
53	    ApiError::new(
54	        ErrorCode::NotFound,
55	        "authorization request not found or expired",
56	    )
57	}
58	
59	/// Signature / authority / binding failures share one message so the surface reveals nothing about
60	/// which check failed.
61	fn approval_rejected() -> ApiError {
62	    ApiError::new(
63	        ErrorCode::AuthenticationRequired,
64	        "consent approval rejected",
65	    )
66	}
67	
68	/// Reduce the wallet's requested granted-scope string to the tokens actually on offer: `atproto` is
69	/// always granted (never optional), and every other token is kept only if it was part of the
70	/// request's snapshotted `requested_scope`. This mirrors `oauth_authorize`'s reduction filter, so a
71	/// tampered/injected token that was never requested cannot add scope — only narrow it.
72	fn reduce_granted_scope(requested_scope: &str, wallet_granted: &str) -> String {
73	    let wallet: Vec<&str> = wallet_granted.split_whitespace().collect();
74	    requested_scope
75	        .split_whitespace()
76	        .filter(|t| *t == "atproto" || wallet.contains(t))
77	        .collect::<Vec<_>>()
78	        .join(" ")
79	}
80	
81	// ── Preview ─────────────────────────────────────────────────────────────────────
82	
83	#[derive(Deserialize)]
84	pub struct ConsentRequestQuery {
85	    /// Typed path: the human-entered `user_code`. Exactly one of `user_code` / `request_id`.
86	    user_code: Option<String>,
87	    /// Handoff path: the `request_id` carried by the "Open in Obsign" link.
88	    request_id: Option<String>,
89	}
90	
91	#[derive(Serialize)]
92	#[serde(rename_all = "camelCase")]
93	pub struct ConsentRequestPreview {
94	    request_id: String,
95	    client_id: String,
96	    client_name: Option<String>,
97	    redirect_uri: String,
98	    origin: Option<String>,
99	    ip: Option<String>,
100	    requested_scope: Vec<String>,
101	    login_hint: Option<String>,
102	}
103	
104	/// `GET /oauth/authorize/consent-request` — the wallet's preview of a pending request, resolved by
105	/// `user_code` (typed) or `request_id` (handoff). Returns 404 for anything not currently pending so
106	/// a guessed code reveals nothing.
107	pub async fn get_consent_request(
108	    State(state): State<AppState>,
109	    Query(query): Query<ConsentRequestQuery>,
110	) -> Result<Json<ConsentRequestPreview>, ApiError> {
111	    let pending = match (&query.user_code, &query.request_id) {
112	        (Some(code), None) => get_pending_by_user_code(&state.db, code).await?,
113	        (None, Some(request_id)) => get_pending_by_request_id(&state.db, request_id).await?,
114	        _ => {
115	            return Err(ApiError::new(
116	                ErrorCode::InvalidRequest,
117	                "exactly one of userCode or requestId is required",
118	            ))
119	        }
120	    };
121	    let pending = pending.filter(|p| p.status == "pending" && !p.is_expired);
122	    let Some(p) = pending else {
123	        return Err(not_approvable());
124	    };
125	    Ok(Json(ConsentRequestPreview {
126	        request_id: p.request_id,
127	        client_id: p.client_id,
128	        client_name: p.client_name,
129	        redirect_uri: p.redirect_uri,
130	        origin: p.origin,
131	        ip: p.ip,
132	        requested_scope: p
133	            .requested_scope
134	            .split_whitespace()
135	            .map(str::to_string)
136	            .collect(),
137	        login_hint: p.login_hint,
138	    }))
139	}
140	
141	// ── Status poll ─────────────────────────────────────────────────────────────────
142	
143	#[derive(Deserialize)]
144	pub struct StatusQuery {
145	    request_id: String,
146	}
147	
148	#[derive(Serialize)]
149	struct StatusResponse {
150	    status: &'static str,
151	}
152	
153	/// `GET /oauth/authorize/status?request_id=…` — the consent page's poll. Throttled per request with
154	/// the `slow_down` discipline (429 when polled faster than `STATUS_POLL_MIN_INTERVAL`), and reports
155	/// a derived `expired` for a lapsed or reclaimed request so the page stops.
156	pub async fn get_authorization_status(
157	    State(state): State<AppState>,
158	    Query(query): Query<StatusQuery>,
159	) -> Response {
160	    // slow_down throttle, reusing the shared poll tracker with a namespaced key so it can't collide
161	    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
162	    {
163	        let key = format!("consent:{}", query.request_id);
164	        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
165	        if let Some(last) = tracker.get(&key) {
166	            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
167	                return (
168	                    StatusCode::TOO_MANY_REQUESTS,
169	                    Json(StatusResponse {
170	                        status: "slow_down",
171	                    }),
172	                )
173	                    .into_response();
174	            }
175	        }
176	        tracker.insert(key, Instant::now());
177	    }
178	

